@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/enum-domain/iso3166-eu> ;
            sh:resultMessage "A cdif:EnumerationDomain should carry a schema:name (human-readable label)" ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A cdif:EnumerationDomain should carry a schema:name (human-readable label)" ;
                    sh:minCount 1 ;
                    sh:path schema1:name ;
                    sh:severity sh:Warning ] ;
            sh:value 42 ] .

